from collections import Counter, deque

def find_components(grid, color):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    singletons = []  # pixels with component size = 1
    other = []  # pixels with component size > 1

    def bfs(start_r, start_c, color):
        comp = [(start_r, start_c)]
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in visited and grid[nr][nc] == color:
                        visited.add((nr, nc))
                        comp.append((nr, nc))
                        queue.append((nr, nc))
        return comp

    for r in range(rows):
        for c in range(cols):
            if (r, c) not in visited:
                comp = bfs(r, c, grid[r][c])
                if len(comp) == 1:
                    # singleton
                    if grid[r][c] != 8:  # ignore single background pixels
                        singletons.append((r, c, grid[r][c]))
                else:
                    for (cr, cc) in comp:
                        other.append((cr, cc, grid[cr][cc]))
    return singletons, other

